'use strict';
let warehouseExpanded=true,caseSectionExpanded=true;
const caseStatuses=['尚未開始','進行中','結案'];
function normalizedCaseStatus(status){return status==='執行中'?'進行中':caseStatuses.includes(status)?status:'尚未開始';}
function caseDate(value){return value?String(value).replaceAll('-','/'):'未填寫';}
function chineseNumber(value){const n=Math.max(1,Number(value)||1),digits=['零','一','二','三','四','五','六','七','八','九'];if(n<10)return digits[n];if(n===10)return'十';if(n<20)return'十'+digits[n%10];if(n<100)return digits[Math.floor(n/10)]+'十'+(n%10?digits[n%10]:'');return String(n);}
function caseBatchLabel(c){return'第'+chineseNumber(c.batch||1)+'批';}
function caseStatusText(status){return siteText(status==='尚未開始'?'caseWaitingLabel':status==='進行中'?'caseRunningLabel':'caseClosedLabel');}
const defaultCaseClosedDateText='結案日 ';
function migrateCases(){state.cases??=[];for(const c of state.cases){c.status=normalizedCaseStatus(c.status);c.batch=Number.isSafeInteger(Number(c.batch))&&Number(c.batch)>0?Number(c.batch):1;c.quantity=Number.isSafeInteger(Number(c.quantity))&&Number(c.quantity)>0?Number(c.quantity):1;}}
function moveItem(list,index,direction,label){const target=index+direction;if(index<0||target<0||target>=list.length)return;[list[index],list[target]]=[list[target],list[index]];addAudit('調整顯示順序',label,'管理後台');persist();if(location.hash==='#admin')renderAdmin();else render();}
function moveCaseWithinStatus(id,direction){const item=state.cases.find(c=>c.id===id);if(!item)return;const indexes=state.cases.map((c,index)=>({c,index})).filter(x=>normalizedCaseStatus(x.c.status)===normalizedCaseStatus(item.status)).map(x=>x.index),current=indexes.indexOf(state.cases.indexOf(item)),target=current+direction;if(current<0||target<0||target>=indexes.length)return;const a=indexes[current],b=indexes[target];[state.cases[a],state.cases[b]]=[state.cases[b],state.cases[a]];addAudit('調整顯示順序',item.name+' · '+caseBatchLabel(item),'案件管理');persist();render();}
function caseCard(c,index,total){return '<article class="case-card"><div class="case-card-line case-card-main"><strong title="'+esc(c.name)+'">'+esc(c.name)+'</strong><span>'+esc(caseBatchLabel(c))+' · '+c.quantity+'套</span><button type="button" class="small" data-case-edit="'+esc(c.id)+'">'+esc(siteText('caseEditButton'))+'</button></div><div class="case-card-line case-card-meta"><span class="case-vendor" title="'+esc(c.vendor||'未填寫')+'">'+esc(c.vendor||'未填寫')+'</span><span>'+esc(siteText('caseClosedDateLabel'))+' '+esc(caseDate(c.closedDate))+'</span><span class="case-card-order"><button type="button" class="small" aria-label="上移" title="上移" data-case-up="'+esc(c.id)+'" '+(index===0?'disabled':'')+'>↑</button><button type="button" class="small" aria-label="下移" title="下移" data-case-down="'+esc(c.id)+'" '+(index===total-1?'disabled':'')+'>↓</button></span></div></article>';}
function caseBoard(){return '<div class="case-board">'+caseStatuses.map(status=>{const list=state.cases.filter(c=>normalizedCaseStatus(c.status)===status);return '<section class="case-lane case-lane-'+(status==='尚未開始'?'waiting':status==='進行中'?'running':'closed')+'"><header><strong>'+esc(caseStatusText(status))+'</strong><span>'+list.length+'</span></header><div class="case-lane-list">'+(list.length?list.map((c,index)=>caseCard(c,index,list.length)).join(''):'<div class="case-lane-empty">'+esc(siteText('caseEmptyText'))+'</div>')+'</div></section>';}).join('')+'</div>';}
async function workbookDownload(sheets,name){if(!await authorizeExport())return;if(!window.XLSX){toast('Excel 元件尚未載入，請重新整理。');return;}const wb=XLSX.utils.book_new();for(const [title,rows] of sheets)XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(rows),title);XLSX.writeFile(wb,name);}
async function exportCases(){if(!await authorizeExport())return;const rows=[['案件名稱','製作批次','製作套數','案件廠商','預計完成日','實際結案日','狀態'],...(state.cases||[]).map(c=>[c.name,caseBatchLabel(c),c.quantity||1,c.vendor||'',c.closedDate||'',c.actualClosedDate||'',normalizedCaseStatus(c.status)])];workbookDownload([['案件管理',rows]],'案件管理資料.xlsx');addAudit('匯出案件管理資料',(state.cases||[]).length+' 筆案件','案件管理');persist();}
async function exportWarehouse(){if(!await authorizeExport())return;const projects=[['專案日期','專案名稱','籃數','庫房位置','零件項數','現有庫存'],...(state.projects||[]).map(p=>[projectDate(p),p.name,p.basketCount??1,p.location||'',p.parts.length,totalStock(p)])],parts=[['專案日期','專案名稱','零件名稱','規格','每套需求','套數','總需求量','已收','現有庫存']];for(const p of state.projects||[])for(const i of p.parts)parts.push([projectDate(p),p.name,i.name,i.spec,i.need,i.sets??1,totalNeed(i),i.received,inStock(p,i.id)]);workbookDownload([['專案總表',projects],['零件與庫存',parts]],'庫房管理資料.xlsx');addAudit('匯出庫房管理資料',(state.projects||[]).length+' 筆專案','庫房管理');persist();}
function enhanceCases(){
 const main=$('main'),demo=$('.demo'),heading=$('.heading'),workspace=$('.workspace'),footer=$('.footer-note');if(!main||!demo||!heading||!workspace||main.querySelector('.case-workspace'))return;
 migrateCases();
 const cases=document.createElement('details');cases.className='workspace case-workspace case-fold';cases.open=caseSectionExpanded;cases.innerHTML='<summary><span>'+esc(siteText('casesTitle'))+'</span></summary><div class="case-head"><small>'+esc(siteText('casesDescription'))+'</small><div class="section-actions"><button type="button" id="export-cases">'+esc(siteText('caseExportButton'))+'</button><button type="button" id="new-case" class="primary">'+esc(siteText('caseNewButton'))+'</button></div></div>'+caseBoard();demo.after(cases);cases.ontoggle=()=>{caseSectionExpanded=cases.open;};
 const fold=document.createElement('details');fold.className='warehouse-fold';fold.open=warehouseExpanded;fold.innerHTML='<summary>'+esc(siteText('heading'))+'</summary>';heading.before(fold);heading.querySelector('h1')?.remove();const headingActions=document.createElement('div');headingActions.className='section-actions';const exportButton=document.createElement('button'),photoExportButton=document.createElement('button');exportButton.type='button';exportButton.id='export-warehouse';exportButton.textContent=siteText('warehouseExportButton');photoExportButton.type='button';photoExportButton.id='export-all-photos-main';photoExportButton.textContent=siteText('warehouseAllPhotoExportButton');photoExportButton.onclick=exportAllPhotos;headingActions.append(exportButton,photoExportButton,$('#new-project'));heading.append(headingActions);fold.append(heading,workspace,footer);fold.ontoggle=()=>{warehouseExpanded=fold.open;};
 const warehouseWords=[['#rename-project','warehouseRenameButton'],['#delete-project','warehouseDeleteButton'],['#import-bom','warehouseImportButton'],['#add-part','warehouseAddPartButton'],['#restore-part','warehouseRestorePartButton'],['#receipt-form button[type="submit"]','warehouseSaveButton'],['#upload-receipts','warehouseReceiptUploadButton']];for(const [selector,key] of warehouseWords){const el=$(selector);if(el)el.textContent=siteText(key);}const detailTitle=$('.detail-title h2');if(detailTitle)detailTitle.textContent=siteText('warehouseDetailTitle');const receiptLabel=$('#receipt-files')?.closest('label');if(receiptLabel?.firstChild)receiptLabel.firstChild.nodeValue=siteText('warehouseReceiptChooseLabel');const historySummary=$('.project-history summary');if(historySummary?.firstChild)historySummary.firstChild.nodeValue=siteText('warehouseHistoryLabel')+'（';
 $('#new-case').onclick=()=>editCase();$('#export-cases').onclick=exportCases;$('#export-warehouse').onclick=exportWarehouse;
 document.querySelectorAll('[data-case-edit]').forEach(el=>el.onclick=()=>editCase(el.dataset.caseEdit));
 document.querySelectorAll('[data-case-up]').forEach(el=>el.onclick=()=>moveCaseWithinStatus(el.dataset.caseUp,-1));
 document.querySelectorAll('[data-case-down]').forEach(el=>el.onclick=()=>moveCaseWithinStatus(el.dataset.caseDown,1));
 document.querySelectorAll('.project').forEach(article=>{const id=article.querySelector('[data-project]')?.dataset.project,index=state.projects.findIndex(p=>p.id===id),controls=document.createElement('div');controls.className='project-order-controls';controls.innerHTML='<button type="button" class="small" data-project-up="'+index+'" '+(index===0?'disabled':'')+'>↑ 上移</button><button type="button" class="small" data-project-down="'+index+'" '+(index===state.projects.length-1?'disabled':'')+'>↓ 下移</button>';article.append(controls);});
 document.querySelectorAll('[data-project-up]').forEach(el=>el.onclick=()=>moveItem(state.projects,Number(el.dataset.projectUp),-1,'庫房專案順序'));
 document.querySelectorAll('[data-project-down]').forEach(el=>el.onclick=()=>moveItem(state.projects,Number(el.dataset.projectDown),1,'庫房專案順序'));
}
function editCase(id,fromAdmin=false){
 migrateCases();const existing=(state.cases||[]).find(c=>c.id===id),c=existing||{id:crypto.randomUUID(),name:'',vendor:'',acceptedDate:'',closedDate:'',status:'尚未開始',batch:1,quantity:1};
 modal(existing?'修改案件資料':'新增案件',field(esc(siteText('caseNameLabel')),'name',c.name,'required maxlength="100"')+field(esc(siteText('caseVendorLabel')),'vendor',c.vendor,'maxlength="100"')+'<div class="form-grid">'+field(esc(siteText('caseBatchLabel')),'batch',c.batch||1,'type="number" min="1" step="1" required')+field(esc(siteText('caseQuantityLabel')),'quantity',c.quantity||1,'type="number" min="1" step="1" required')+field(esc(siteText('caseClosedDateLabel')),'closedDate',c.closedDate,'type="date"')+field(esc(siteText('caseActualClosedDateLabel'))+'（結案時填寫）','actualClosedDate',c.actualClosedDate||'','type="date"')+'</div><label class="field">'+esc(siteText('caseStatusLabel'))+'<select name="status">'+caseStatuses.map(s=>'<option value="'+esc(s)+'" '+(normalizedCaseStatus(c.status)===s?'selected':'')+'>'+esc(caseStatusText(s))+'</option>').join('')+'</select></label>',esc(siteText('caseSaveButton')),async fd=>{const name=String(fd.get('name')||'').trim();if(!name)error('請填寫案件名稱。');const quantity=integer(fd.get('quantity'),1,Number.MAX_SAFE_INTEGER),batch=integer(fd.get('batch'),1,9999);if(state.cases.some(x=>x.id!==c.id&&x.name.trim().toLowerCase()===name.toLowerCase()&&Number(x.batch||1)===batch))error('此案件的製作批次已存在，請改用其他批次。');const next={...c,name,vendor:String(fd.get('vendor')||'').trim(),closedDate:String(fd.get('closedDate')||''),status:normalizedCaseStatus(String(fd.get('status'))),batch,quantity};next.actualClosedDate=next.status==='結案'?String(fd.get('actualClosedDate')||''):'';if(next.status==='結案'&&c.status!=='結案'){next.actualClosedDate||=taipeiDate();if(!await confirmAction('確定結案？實際結案日：'+next.actualClosedDate+'。庫房庫存不會清除。'))return;}if(c.status==='結案'&&next.status!=='結案'&&!await confirmAction('確定重新開啟案件？實際結案日期會清空，預計完成日與操作紀錄會保留。'))return;if(existing)Object.assign(existing,next);else state.cases.unshift(next);addAudit(existing?'修改管理案件項目':'新增管理案件項目',next.name+' · '+caseBatchLabel(next)+' · '+next.quantity+'套 · '+next.status+' · 實際結案日：'+(next.actualClosedDate||'未填'),'案件管理 > '+next.name);persist();if(fromAdmin){$('#modal').close();renderAdmin();toast(existing?'案件資料已更新':'案件已建立');}else done(existing?'案件資料已更新':'案件已建立');});
}
const renderBeforeCases=render;render=function(){renderBeforeCases();enhanceCases();};
function enhanceAdminCases(){const main=$('main');if(!main||$('#admin-cases'))return;migrateCases();const cards=main.querySelectorAll('.admin-card'),card=document.createElement('details');card.id='admin-cases';card.className='admin-card';card.innerHTML='<summary><h2>'+esc(siteText('casesTitle'))+'</h2><span>'+esc(adminText('expandLabel'))+'</span></summary><div class="admin-card-body"><p>可在後台建立、修改、排序或刪除所有案件資料。</p>'+(state.cases||[]).map((c,i)=>'<div class="admin-row"><strong>'+esc(c.name)+' · '+esc(caseBatchLabel(c))+' · '+c.quantity+'套</strong><span>'+esc(c.vendor||'未填廠商')+' · '+esc(caseStatusText(normalizedCaseStatus(c.status)))+'</span><button type="button" data-admin-case-up="'+i+'" '+(i===0?'disabled':'')+'>上移</button><button type="button" data-admin-case-down="'+i+'" '+(i===(state.cases||[]).length-1?'disabled':'')+'>下移</button><button type="button" data-admin-case="'+esc(c.id)+'">'+esc(siteText('caseEditButton'))+'</button><button type="button" class="danger-button" data-admin-case-delete="'+esc(c.id)+'">刪除</button></div>').join('')+'<div class="admin-actions"><button type="button" id="edit-case-text">修改案件管理文字</button><button type="button" id="admin-export-cases">'+esc(siteText('caseExportButton'))+'</button><button type="button" id="admin-new-case">'+esc(siteText('caseNewButton'))+'</button></div></div>';if(cards[0])cards[0].after(card);else main.append(card);$('#edit-case-text').onclick=()=>editSiteText('cases');$('#admin-new-case').onclick=()=>editCase(undefined,true);$('#admin-export-cases').onclick=exportCases;document.querySelectorAll('[data-admin-case]').forEach(el=>el.onclick=()=>editCase(el.dataset.adminCase,true));document.querySelectorAll('[data-admin-case-up]').forEach(el=>el.onclick=()=>moveItem(state.cases,Number(el.dataset.adminCaseUp),-1,'案件管理順序'));document.querySelectorAll('[data-admin-case-down]').forEach(el=>el.onclick=()=>moveItem(state.cases,Number(el.dataset.adminCaseDown),1,'案件管理順序'));document.querySelectorAll('[data-admin-case-delete]').forEach(el=>el.onclick=async()=>{const index=state.cases.findIndex(c=>c.id===el.dataset.adminCaseDelete);if(index<0||!(await confirmAction('確定刪除案件「'+state.cases[index].name+'」？')))return;const removed=state.cases.splice(index,1)[0];addAudit('刪除管理案件項目',removed.name+' · '+caseBatchLabel(removed),'案件管理 > '+removed.name);persist();renderAdmin();toast('案件已刪除');});}
